styles['Normal'].font.name='Calibri'; styles['Normal'].font.size=Pt(11); styles['Normal']._element.rPr.rFonts.set(qn('w:ascii'),'Calibri'); styles['Normal']._element.rPr.rFonts.set(qn('w:hAnsi'),'Calibri')
for name,size,color,before,after in [('Heading 1',17,BLUE,12,7),('Heading 2',13,NAVY,8,4),('Heading 3',11,NAVY,6,3)]:
    st=styles[name]; st.font.name='Calibri'; st.font.size=Pt(size); st.font.bold=True; st.font.color.rgb=RGBColor.from_string(color); st._element.rPr.rFonts.set(qn('w:ascii'),'Calibri'); st._element.rPr.rFonts.set(qn('w:hAnsi'),'Calibri'); st.paragraph_format.space_before=Pt(before); st.paragraph_format.space_after=Pt(after)
