title=p(doc,'Complete Placement Interview Handbook',after=10,align=WD_ALIGN_PARAGRAPH.CENTER); title.runs[0].font.size=Pt(28); title.runs[0].font.color.rgb=RGBColor.from_string(NAVY); title.runs[0].bold=True
sub=p(doc,'A broad, honest technical guide to the architecture, implementation choices, interview questions and production thinking behind your final-year B.Tech project.',after=22,align=WD_ALIGN_PARAGRAPH.CENTER); sub.runs[0].italic=True; sub.runs[0].font.color.rgb=RGBColor.from_string('4E647A')
table(doc,[('Purpose','Build interview-ready understanding, not memorised buzzwords.'),('How to revise','Read the pitch and mental map first; then take one chapter per study session.'),('Evidence rule','Separate implemented features, verified tests and future improvements.'),('Version','Prepared for Task Force Orbit placement preparation • August 2026')])
p(doc,'How to use this document',style='Heading 2'); bullet(doc,'Answer in layers: definition → Task Force Orbit example → trade-off → next improvement.'); bullet(doc,'Never invent metrics, security guarantees or passing tests. Honest scope is a strength.'); bullet(doc,'Use the source list for concepts, but describe your own implementation in your own words.')

for n,(title,idea,implementation,tradeoff) in enumerate(topics,1):
    doc.add_page_break(); p(doc,f'CHAPTER {n:02d}',after=2).runs[0].font.color.rgb=RGBColor.from_string('6D8296'); doc.paragraphs[-1].runs[0].font.size=Pt(9); doc.paragraphs[-1].runs[0].bold=True
    h=p(doc,title,style='Heading 1');
    p(doc,'Essential idea',style='Heading 2'); p(doc,idea,after=8)
    table(doc,[('Task Force Orbit',implementation),('Decision / trade-off',tradeoff)])
    p(doc,'Interview-ready answer',style='Heading 2')
    p(doc,f'“{idea} In Task Force Orbit, {implementation.lower()} The key trade-off is that {tradeoff.lower()}”',after=8)
    p(doc,'Likely follow-up questions',style='Heading 2')
    bullet(doc,f'What problem does this solve, and what would fail without it?')
    bullet(doc,f'Why was this choice appropriate for a final-year, production-minded project rather than the most complex possible design?')
    bullet(doc,f'What is one limitation today, and how would you validate the next upgrade?')
    p(doc,'Memory anchor',style='Heading 2'); p(doc, f'{title}: problem → implementation → control → trade-off → next step.',after=3)

doc.add_page_break(); p(doc,'APPENDIX A — 15 rapid-fire questions',style='Heading 1')
rapid=[('Authentication vs authorization','Authentication proves identity; authorization decides permitted action.'),('Why refresh tokens?','They renew short-lived access without asking for password repeatedly.'),('Why httpOnly cookie?','JavaScript cannot read it, reducing token theft through XSS.'),('Why private S3?','Files should not become public merely because someone guesses a URL.'),('Why signed URL?','It grants short-lived, specific object access after API authorization.'),('Why rate limit?','To slow abuse and protect service capacity.'),('Why database constraint?','It remains correct even with concurrent application requests.'),('Why validation twice?','Client for user experience; server for trust boundary.'),('Why role check server-side?','UI can be bypassed; server owns the protected data.'),('Why MongoDB?','Document-oriented iteration matched current product access patterns.'),('Why not WebSockets yet?','Polling met freshness needs with simpler operation.'),('What is optimistic UI?','Show local result immediately, then reconcile/persist server result.'),('What does CORS do?','Browser-origin policy; it is not an identity mechanism.'),('What is idempotency?','Repeating an operation produces the same intended final effect.'),('What is your proud design choice?','Controlled review states plus role checks make collaboration rules explicit.')]
for q,a in rapid: p(doc,q,style='Heading 3'); p(doc,a,after=5)
doc.add_page_break(); p(doc,'APPENDIX B — Interviewer expectations and answer checklist',style='Heading 1')
for item in ['State the business problem before the technology.','Name the boundary: browser, API, database, cloud object store or email provider.','Give one exact code-level/project example.','Name a trade-off and why it was acceptable.','Say how you verified it.','Name one realistic future improvement without pretending it already exists.','Keep sensitive values and private credentials out of demonstration screens.']:
    bullet(doc,item)
p(doc,'Research sources',style='Heading 2')
for s in ['OWASP Authentication Cheat Sheet — https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html','OWASP Session Management Cheat Sheet — https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html','OWASP REST Security Cheat Sheet — https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html','MDN CORS Guide — https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS','MongoDB: Embed versus References — https://www.mongodb.com/docs/v7.2/data-modeling/concepts/embedding-vs-references/','AWS: Presigned URLs — https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-presigned-url.html','Vercel: Secure every step of a modern SDLC — https://assets.vercel.com/image/upload/v1745532177/front/security/Secured_modern_SDLC.pdf','Indeed: Entry-level software engineer interview questions — https://www.indeed.com/career-advice/interviewing/entry-level-software-engineer-interview-questions']:
    p(doc,s,after=4)
doc.add_page_break(); p(doc,'APPENDIX C — MongoDB and Mongoose query brain map',style='Heading 1')
p(doc,'MongoDB stores documents; Mongoose is the Node.js layer that gives those documents schemas, models and query methods. A Task model maps JavaScript calls to the MongoDB task collection.',after=5)
p(doc,'1. Board query: filter, then sort',style='Heading 2')
p(doc,'find() returns matching documents; sort() orders the project board newest first.',after=3)
p(doc,'Before indexing — application query',style='Heading 3')
code_block(doc,'Task.find({ project: projectId })\n  .populate("assignedTo", "avatar username fullName")\n  .sort({ createdAt: -1 });')
p(doc,'Before the matching index exists, MongoDB may use a COLLSCAN (collection scan) and then a separate sort. The JavaScript query is correct, but it has more work as the collection grows.',after=3)
p(doc,'After indexing — same application query, faster database plan',style='Heading 3')
code_block(doc,'Task.find({ project: projectId })\n  .populate("assignedTo", "avatar username fullName")\n  .sort({ createdAt: -1 });\n\n// MongoDB uses: IXSCAN on project_1_createdAt_-1')
p(doc,'The query code does not change. taskSchema.index({ project: 1, createdAt: -1 }) gives MongoDB an ordered path for the filter and sort. IXSCAN means “index scan.”',after=3)
p(doc,'2. Personal deadline query: ObjectId equality plus date range',style='Heading 2')
p(doc,'$gte means “greater than or equal to”; $lt means “less than.”',after=3)
code_block(doc,'Task.find({\n  assignedTo: userId,\n  dueDate: { $gte: startOfToday, $lt: startOfTomorrow }\n}).sort({ dueDate: 1 });')
p(doc,'3. Notification feed: one recipient, newest first',style='Heading 2')
code_block(doc,'Notification.find({ recipient: userId })\n  .sort({ createdAt: -1 });')
p(doc,'4. What an index changes',style='Heading 2')
p(doc,'An index is a smaller ordered lookup structure. This one matches “recipient, then newest first,” so MongoDB can locate and order a user’s feed more efficiently.',after=3)
code_block(doc,'notificationSchema.index({ recipient: 1, createdAt: -1 });')
doc.add_page_break(); p(doc,'5. Index verification and trade-offs',style='Heading 2')
p(doc,'Brain map: schema describes data → model exposes methods → Mongoose sends the query → MongoDB query planner selects an execution plan → the selected index narrows and orders the search.',after=5)
p(doc,'I verified the added indexes with explain(), a read-only query-plan inspection. It shows whether MongoDB selects IXSCAN or falls back to COLLSCAN.',after=3)
code_block(doc,'await Task.find({ project: projectId })\n  .sort({ createdAt: -1 })\n  .explain("queryPlanner");')
p(doc,'Current indexes: User email/username, unique project name, unique project-invite { project, email }, Softboard owner, Task { project, createdAt }, Task { assignedTo, dueDate }, Notification { recipient, createdAt }, Activity { project, createdAt }, and unique ProjectMember { project, user }. The five query indexes were verified with explain(): MongoDB selected project_1_createdAt_-1, assignedTo_1_dueDate_1, recipient_1_createdAt_-1, and project_1_user_1. Indexes consume storage and add write work, so they should match real query patterns.',after=4)
p(doc,'Interview answer',style='Heading 2')
p(doc,'“Mongoose builds my query, while MongoDB executes it. Task.find filters board tasks by project and sort orders them by creation time. I kept the same query and added a compound { project, createdAt } index, so MongoDB can choose an IXSCAN rather than scanning and separately sorting a growing collection. I add indexes only for frequent query patterns because they speed reads but add storage and write overhead.”',after=4)
